const issues = $input.first().json.issues || [];
const keys = new Set();
for (const i of issues) {
  for (const l of ((i.fields && i.fields.issuelinks) || [])) {
    if (((l.type && l.type.name) || '').trim() !== 'Localization ticket') continue;
    const o = l.inwardIssue || l.outwardIssue;
    if (o && o.key && o.key.indexOf('INTERNAT-') !== 0) keys.add(o.key);
  }
}
const list = Array.from(keys);
return [{ json: { llrs: issues, productJql: list.length ? 'key in (' + list.join(',') + ')' : 'key = INTERNAT-1' } }];

const NL = String.fromCharCode(10);
const llrs = $('Collect product keys').first().json.llrs || [];
const products = {};
for (const p of ($input.first().json.issues || [])) products[p.key] = p.fields || {};
const today = $today;
const todayISO = today.toISODate();
const win = [0, 1, 2].map(n => today.plus({ days: n }).toISODate());
const windowEnd = win[2];
const dayFmt = iso => DateTime.fromISO(iso).toFormat('d LLL');
const esc = s => String(s || '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const nice = s => String(s || '').toLowerCase().split(' ').map(x => (x === 'qa' || x === 'stg' || x === 'uat') ? x.toUpperCase() : x).join(' ');
const upFirst = s => s.charAt(0).toUpperCase() + s.slice(1);
const stripTags = s => { s = String(s || '').trim(); while (s.charAt(0) === '[') { const j = s.indexOf(']'); if (j < 0) break; s = s.slice(j + 1).trim(); } return s; };
const shorten = (s, n) => s.length > n ? s.slice(0, n - 1).trim() + '…' : s;
const productName = s => { s = String(s || ''); const j = s.lastIndexOf('] - '); return j < 0 ? '' : stripTags(s.slice(j + 4)).split(' - ')[0].trim(); };
const link = k => '<https://futuremedia.atlassian.net/browse/' + k + '|' + k + '>';
const ORDER = ['dev verification', 'prod verification', 'in progress', 'to do', 'blocked'];
const rank = s => { const i = ORDER.indexOf(String(s || '').toLowerCase()); return i < 0 ? 2.5 : i; };
const testable = s => { const x = String(s || '').toLowerCase(); return x === 'dev verification' || x === 'prod verification'; };
const NEAR = ['pending qa', 'in qa', 'qa', 'ready for qa', 'in code review', 'ready for stg', 'pending prod'];

const live = [], soon = [], other = [];
for (const i of llrs) {
  const f = i.fields || {};
  const linked = (f.issuelinks || [])
    .filter(l => ((l.type && l.type.name) || '').trim() === 'Localization ticket')
    .map(l => l.inwardIssue || l.outwardIssue)
    .filter(o => o && o.key && o.key.indexOf('INTERNAT-') !== 0);
  if (!linked.length) continue;
  const p = products[linked[0].key];
  if (!p) continue;
  const versions = p.fixVersions || [];
  const released = versions.filter(v => v.released && v.releaseDate && v.releaseDate <= todayISO).sort((a, b) => b.releaseDate.localeCompare(a.releaseDate));
  const upcoming = versions.filter(v => !v.released && v.releaseDate && v.releaseDate >= todayISO).sort((a, b) => a.releaseDate.localeCompare(b.releaseDate));
  const done = !!(p.status && p.status.statusCategory && p.status.statusCategory.key === 'done');
  const pStatus = (p.status && p.status.name) || '';
  const status = (f.status && f.status.name) || '';
  const row = { key: i.key, status: status, title: esc(shorten(stripTags(p.summary), 80)), product: esc(productName(f.summary)) };
  if (upcoming.length && upcoming[0].releaseDate <= windowEnd) {
    row.date = upcoming[0].releaseDate;
    row.versions = esc(upcoming.filter(v => v.releaseDate === row.date).map(v => v.name).join(' / '));
    soon.push(row);
  } else if (done || released.length) {
    row.date = released.length ? released[0].releaseDate : '';
    live.push(row);
  } else if (testable(status) || NEAR.indexOf(pStatus.toLowerCase()) >= 0 || upcoming.length) {
    row.next = upcoming.length ? upcoming[0].releaseDate : '';
    row.pStatus = pStatus;
    other.push(row);
  }
}
live.sort((a, b) => rank(a.status) - rank(b.status) || (b.date || '').localeCompare(a.date || ''));
soon.sort((a, b) => a.date.localeCompare(b.date) || rank(a.status) - rank(b.status));
other.sort((a, b) => rank(a.status) - rank(b.status));

const dayLabel = iso => iso === win[0] ? 'today' : (iso === win[1] ? 'tomorrow' : DateTime.fromISO(iso).toFormat('cccc'));
const soonDates = Array.from(new Set(soon.map(r => r.date))).sort();
let soonTitle = 'Releasing in the next 2 days';
let soonShort = 'releasing in the next 2 days';
if (soonDates.length === 1) {
  soonTitle = 'Releasing ' + dayLabel(soonDates[0]) + ', ' + dayFmt(soonDates[0]);
  soonShort = 'releasing ' + dayLabel(soonDates[0]);
} else if (soonDates.length > 1) {
  soonTitle = 'Releasing ' + dayFmt(soonDates[0]) + ' – ' + dayFmt(soonDates[soonDates.length - 1]);
  soonShort = 'releasing by ' + dayFmt(soonDates[soonDates.length - 1]);
}
const multiDay = soonDates.length > 1;
const paren = parts => { const t = parts.filter(Boolean).join(', '); return t ? ' (' + t + ')' : ''; };
const tag = s => '_' + upFirst(nice(s)) + '_';

const liveLines = live.map(r => '• ' + link(r.key) + ': ' + r.title + paren([r.product, r.date ? 'live ' + dayFmt(r.date) : '']) + '. ' + tag(r.status));
const soonLines = soon.map(r => '• ' + link(r.key) + ': ' + r.title + paren([(r.product + ' ' + r.versions).trim(), multiDay ? dayFmt(r.date) : '']) + '. ' + tag(r.status));
const otherLines = other.map(r => '• ' + link(r.key) + ': ' + r.title + paren([r.product, r.next ? 'release ' + dayFmt(r.next) : (r.pStatus ? 'product ' + nice(r.pStatus) : '')]) + '. ' + tag(r.status));

const rel = {};
for (const r of soon) {
  const label = (r.product + ' ' + r.versions).trim();
  rel[r.date] = rel[r.date] || [];
  if (rel[r.date].indexOf(label) < 0) rel[r.date].push(label);
}
const relParts = [];
if (!soon.length) {
  relParts.push('nothing in the next 2 days');
} else {
  if (!rel[win[0]]) relParts.push('nothing today');
  for (const d of win) {
    if (rel[d]) relParts.push((d === win[0] ? 'today' : dayLabel(d) + ' (' + dayFmt(d) + ')') + ': ' + rel[d].join(' and '));
  }
}

const p1 = live.filter(r => testable(r.status)).map(r => link(r.key));
const p2 = soon.filter(r => testable(r.status)).map(r => link(r.key));
const pl = [];
if (p1.length) pl.push('Already live, LLR not yet verified: ' + p1.join(', '));
if (p2.length) pl.push(upFirst(soonShort) + ': ' + p2.join(', '));

const lines = ['*🧪 i18n QA, ' + today.toFormat('ccc d LLL') + '*', '*Releases:* ' + relParts.join(' · ')];
if (pl.length) {
  lines.push('*Priority:*');
  pl.forEach((t, n) => lines.push((n + 1) + '. ' + t));
} else {
  lines.push('*Priority:* nothing ready to test yet');
}
lines.push('*Totals:* ' + live.length + ' already live · ' + soon.length + ' ' + soonShort + ' · ' + other.length + ' others');
if (live.length + soon.length + other.length) lines.push('Full lists in the thread 🧵');

const replies = [];
if (live.length) replies.push('*Already live, LLR not yet verified*' + NL + liveLines.join(NL));
if (soon.length) replies.push('*' + soonTitle + '*' + NL + soonLines.join(NL));
if (other.length) replies.push('*Others*' + NL + otherLines.join(NL));

return [{ json: { main: lines.join(NL), replies: replies } }];

const res = $input.first().json;
const ts = res.message_timestamp || res.ts || (res.message && res.message.ts);
const replies = $('Build QA summary').first().json.replies || [];
return replies.map(t => ({ json: { text: t, thread_ts: ts } }));

